import { openAIService } from "../../shared/index.js";
import { SIMILARITY_MATCH_COUNT, EMBEDDING_MODEL_NAME } from "../../shared/constants.js"
import { supabase } from "../../../config.js";

export async function retrieveSimilarDocs(query) {
  /**
   * The vector generated by OpenAI for the query text input
   * to be used for similarity search
   */
  const embeddings = await openAIService.embeddings.create({
    model: EMBEDDING_MODEL_NAME,
    input: query,
  });

  const { embedding: queryEmbedding } = embeddings.data[0];

  /**
   * Retrieve similar docs from supabase based on embeddings
   * @param queryEmbedding The embedding vector for the query
   * @param matchCount The number of similar documents to retrieve
   * @param matchThreshold The similarity threshold for matching documents
   */
  const { data: documents, error: matchError } = await supabase.rpc(
    'match_documents',
    {
      query_embedding: queryEmbedding,
      match_count: SIMILARITY_MATCH_COUNT,
      match_threshold: 0.3,
    }
  );

  if (matchError)
    throw new Error(`Failed to fetch docs from supabase. Error: ${matchError}`)

  return documents
}